1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Customer {
9	  yearsWithMHPCO: number;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	/** The MHPCO's catalogue of insurable items. Base premium and insurance value are
60	 *  independent figures; they are listed together because they describe one item type. */
61	const ITEM_CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
62	  sword: { basePremium: 100, insuranceValue: 1000 },
63	  amulet: { basePremium: 60, insuranceValue: 600 },
64	  staff: { basePremium: 80, insuranceValue: 800 },
65	  potion: { basePremium: 40, insuranceValue: 400 },
66	  rune: { basePremium: 25, insuranceValue: 250 },
67	  moonstone: { basePremium: 25, insuranceValue: 250 },
68	};
69	
70	const catalogueEntry = (item: Item): { basePremium: number; insuranceValue: number } => {
71	  const entry = ITEM_CATALOGUE[item.type];
72	  if (entry === undefined) {
73	    throw new Error(`The MHPCO does not insure items of type: ${item.type}`);
74	  }
75	  return entry;
76	};
77	
78	const itemBasePremium = (item: Item): number => catalogueEntry(item).basePremium;
79	
80	const BLOCK_SIZE = 3;
81	const BLOCK_BASE_PREMIUM = 60;
82	
83	const sumOfItemBasePremiums = (items: Item[]): number =>
84	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
85	
86	const itemsGroupedByType = (items: Item[]): Item[][] => {
87	  const byType = new Map<string, Item[]>();
88	  for (const item of items) {
89	    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
90	  }
91	  return [...byType.values()];
92	};
93	
94	const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;
95	
96	const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
97	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);
98	
99	const policyBasePremium = (items: Item[]): number =>
100	  itemsGroupedByType(items).reduce(
101	    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
102	    0,
103	  );
104	
105	const withFirstInsuranceSurcharge = (policyBase: number): number =>
106	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
107	
108	const roundPremiumInMHPCOsFavor = Math.ceil;
109	
110	const HIGH_ENCHANTMENT_THRESHOLD = 5;
111	
112	const isCursed = (item: Item): boolean => item.cursed === true;
113	
114	/** An item with no recorded enchantment is treated as wholly unenchanted. */
115	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
116	
117	const isHighlyEnchanted = (item: Item): boolean =>
118	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD;
119	
120	interface RiskSurcharge {
121	  appliesTo: (item: Item) => boolean;
122	  rateOfBasePremium: number;
123	}
124	
125	const RISK_SURCHARGES: RiskSurcharge[] = [
126	  { appliesTo: isCursed, rateOfBasePremium: 0.5 },
127	  { appliesTo: isHighlyEnchanted, rateOfBasePremium: 0.3 },
128	];
129	
130	const itemRiskSurcharge = (item: Item): number =>
131	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
132	    (sum, surcharge) => sum + itemBasePremium(item) * surcharge.rateOfBasePremium,
133	    0,
134	  );
135	
136	const totalRiskSurcharges = (items: Item[]): number =>
137	  items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
138	
139	/** Who the policy is for, and where it sits in their history with the MHPCO. */
140	interface QuoteContext {
141	  customer: Customer;
142	  isFollowUpContract: boolean;
143	}
144	
145	const LOYALTY_DISCOUNT = 0.2;
146	const LOYALTY_THRESHOLD_YEARS = 2;
147	
148	const isLoyal = (context: QuoteContext): boolean =>
149	  context.customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
150	
151	const loyaltyDiscount = (policyBase: number, context: QuoteContext): number =>
152	  isLoyal(context) ? policyBase * LOYALTY_DISCOUNT : 0;
153	
154	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
155	
156	const followUpContractDiscount = (policyBase: number, context: QuoteContext): number =>
157	  context.isFollowUpContract ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
158	
159	const policyWidePremium = (policyBase: number, context: QuoteContext): number =>
160	  withFirstInsuranceSurcharge(policyBase) -
161	  loyaltyDiscount(policyBase, context) -
162	  followUpContractDiscount(policyBase, context);
163	
164	const premiumBeforeFee = (items: Item[], context: QuoteContext): number =>
165	  policyWidePremium(policyBasePremium(items), context) + totalRiskSurcharges(items);
166	
167	const quotePremium = (items: Item[], context: QuoteContext): number =>
168	  roundPremiumInMHPCOsFavor(premiumBeforeFee(items, context) + PROCESSING_FEE);
169	
170	/** Payouts round down, premiums round up — both in the MHPCO's favor. */
171	const roundPayoutInMHPCOsFavor = Math.floor;
172	
173	const DEDUCTIBLE_PER_DAMAGE = 100;
174	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
175	
176	const itemInsuranceValue = (item: Item): number => catalogueEntry(item).insuranceValue;
177	
178	const insuranceSum = (items: Item[]): number =>
179	  items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
180	
181	interface Policy {
182	  items: Item[];
183	  remainingCap: number;
184	}
185	
186	/** The high-enchantment clause: damage to a heavily enchanted item is reimbursed at half
187	 *  rate, on the theory that its enchantment shares the blame. Distinct from the quote-time
188	 *  high-enchantment surcharge, which has its own (lower) threshold. */
189	const HIGH_ENCHANTMENT_CLAUSE_THRESHOLD = 8;
190	const HIGH_ENCHANTMENT_CLAUSE_RATE = 0.5;
191	
192	const fallsUnderHighEnchantmentClause = (item: Item): boolean =>
193	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_CLAUSE_THRESHOLD;
194	
195	const damageAfterEnchantmentClause = (damage: Damage, damagedItem: Item): number =>
196	  fallsUnderHighEnchantmentClause(damagedItem)
197	    ? damage.amount * HIGH_ENCHANTMENT_CLAUSE_RATE
198	    : damage.amount;
199	
200	/** A damage entry together with the one insured item it is claimed against. */
201	interface ClaimedDamage {
202	  damage: Damage;
203	  damagedItem: Item;
204	}
205	
206	const settledAmount = ({ damage, damagedItem }: ClaimedDamage): number =>
207	  damageAfterEnchantmentClause(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
208	
209	/** A damage entry is only claimable if it describes a loss the MHPCO could owe money for. */
210	const rejectUnclaimableDamage = (damage: Damage): void => {
211	  if (damage.amount < 0) {
212	    throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
213	  }
214	};
215	
216	/** Each damage entry consumes its own insured item, so a policy covering two swords can
217	 *  suffer two separate sword damages — but never more than it covers. Pairing every damage
218	 *  up front keeps the consumption explicit rather than hiding it in the payout sum. */
219	const pairDamagesWithInsuredItems = (
220	  damages: Damage[],
221	  insuredItems: Item[],
222	): ClaimedDamage[] => {
223	  const unclaimedItems = [...insuredItems];
224	  return damages.map((damage) => {
225	    rejectUnclaimableDamage(damage);
226	    const index = unclaimedItems.findIndex((item) => item.type === damage.itemType);
227	    if (index === -1) {
228	      throw new Error(`Item not covered by policy: ${damage.itemType}`);
229	    }
230	    const [damagedItem] = unclaimedItems.splice(index, 1);
231	    return { damage, damagedItem };
232	  });
233	};
234	
235	/** What the incident is worth before the policy's cap is taken into account. */
236	const grossIncidentPayout = (incident: Incident, insuredItems: Item[]): number =>
237	  pairDamagesWithInsuredItems(incident.damages, insuredItems).reduce(
238	    (sum, pairing) => sum + settledAmount(pairing),
239	    0,
240	  );
241	
242	/** A policy never pays out more than the cap it has left. */
243	const cappedAtRemainingCap = (grossPayout: number, policy: Policy): number =>
244	  Math.min(grossPayout, policy.remainingCap);
245	
246	/** A claim draws down the policy's remaining cap, so settling one yields a new policy state. */
247	const settleClaim = (policy: Policy, incident: Incident): [ClaimResult, Policy] => {
248	  const grossPayout = roundPayoutInMHPCOsFavor(grossIncidentPayout(incident, policy.items));
249	  const payout = cappedAtRemainingCap(grossPayout, policy);
250	  const remainingCap = policy.remainingCap - payout;
251	  return [{ payout, remainingCap }, { items: policy.items, remainingCap }];
252	};
253	
254	const openPolicy = (items: Item[]): Policy => ({
255	  items,
256	  remainingCap: insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
257	});
258	
259	const findPolicy = (policies: Map<number, Policy>, policyRef: number): Policy => {
260	  const policy = policies.get(policyRef);
261	  if (policy === undefined) {
262	    throw new Error(`Unknown policy: ${policyRef}`);
263	  }
264	  return policy;
265	};
266	
267	/** A quote is a follow-up contract when the customer has already taken out a policy
268	 *  earlier in the scenario. */
269	const isPrecededByAQuote = (steps: Step[], stepIndex: number): boolean =>
270	  steps.slice(0, stepIndex).some((earlier) => earlier.op === "quote");
271	
272	export const runScenario = (scenario: Scenario): ScenarioResult => {
273	  const policies = new Map<number, Policy>();
274	
275	  const runStep = (step: Step, stepIndex: number): StepResult => {
276	    if (step.op === "quote") {
277	      policies.set(stepIndex, openPolicy(step.items));
278	      const context = {
279	        customer: scenario.customer,
280	        isFollowUpContract: isPrecededByAQuote(scenario.steps, stepIndex),
281	      };
282	      return { premium: quotePremium(step.items, context) };
283	    }
284	
285	    const [result, settledPolicy] = settleClaim(
286	      findPolicy(policies, step.policy),
287	      step.incident,
288	    );
289	    policies.set(step.policy, settledPolicy);
290	    return result;
291	  };
292	
293	  return { results: scenario.steps.map(runStep) };
294	};
